CREATE PROCEDURE p()
BEGIN
  DECLARE done INT DEFAULT FALSE;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
  IF done THEN
    SELECT CASE WHEN done THEN 1 ELSE 0 END;
  END IF;
  CASE done
    WHEN TRUE THEN SELECT 1;
    ELSE BEGIN SELECT 2; END;
  END CASE;
  lbl: LOOP
    LEAVE lbl;
  END LOOP lbl;
END;
SELECT 2;
BEGIN NOT ATOMIC
  SELECT 3;
END;
BEGIN;
UPDATE t SET a = 1;
COMMIT;
ALTER TABLE t ADD COLUMN begin INT;
SELECT 4;
